sys_ux_data_broker_transform.props:
[
  {
    "name": "itemType",
    "label": "Item type",
    "fieldType": "string",
    "mandatory": true,
    "defaultValue": "folder"
  },
  {
    "name": "itemId",
    "label": "Item ID",
    "fieldType": "string",
    "mandatory": true
  },
  {
    "name": "sharedLink",
    "label": "Shared link (ai-chat only)",
    "fieldType": "string",
    "mandatory": false
  }
]

sys_ux_data_broker_transform.script:
function transform(input) {
    return new BoxEmbedService().build(input.itemType, input.itemId, 'Workspace', input.sharedLink);
}
